fields.InputDefinition:
{
  "goal": "In the Version History app (application switcher dropdown next to the logo → 'Version History'), click the 'Diff Viewer' item in the left navigation. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) diff-mode-toggle — confirm two mode buttons appear ('Label vs Current' and 'Label vs Label'); switch to 'Label vs Label' and confirm a second 'To label' selector plus a swap button appear, then switch back to 'Label vs Current' and confirm a 'Current State' indicator appears; (2) run-comparison — keeping 'Label vs Current' mode, if the 'Compare label' dropdown has labels select one and click Compare and confirm a diff summary with Added / Removed / Modified / Unchanged counts renders (or a 'No differences found' state); if the dropdown is empty, confirm the Compare button stays disabled and the 'Select labels to compare' prompt is shown. Either responsive outcome is success. Keep going until both sections are done. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "diff-mode-toggle",
      "instruction": "toggle Diff Viewer modes",
      "visualCriteria": [
        "The Diff Viewer shows two mode buttons (Label vs Current / Label vs Label); selecting Label vs Label reveals a second 'To label' selector and a swap control, and selecting Label vs Current shows a 'Current State' indicator"
      ]
    },
    {
      "name": "run-comparison",
      "instruction": "run a label-to-current comparison",
      "visualCriteria": [
        "Selecting a label and clicking Compare produces a diff summary with Added/Removed/Modified/Unchanged counts (or a 'No differences found' state); if no labels exist, the Compare button is disabled and a 'Select labels to compare' prompt is shown, and the workflow responds without hanging"
      ]
    }
  ]
}
